def calculate_total_score(player1_score, player2_score, player3_score):
    total = 0
    for score in (player1_score, player2_score, player3_score):
        if score < 20 or score > 29:
            total += score
    return total

class Package:
    def __init__(self, name, version, description=None):
        self.name = name
        self.version = version
        self.description = description

    def install(self):
        print(f'Installing {self.name} version {self.version}...')

    def __str__(self):
        return f'{self.name} version {self.version}'

class Deployment:
