class ChatUser:
    def __init__(self, name, favorites=None):
        if favorites is None:
            favorites = set()
        self.name = name
        self.favorites = favorites
        self.num_messages = 0

    def send_message(self, num):
        self.num_messages += num

    def react_to_message(self, num_reactions):
        for _ in range(num_reactions):
            print('Reacted!')
        self.num_messages += num_reactions

    def __str__(self):
        return self.name

class ServiceRegistry:
    def __init__(self, name, service_instances=None, deployments=None):
        self.name = name
        self.service_instances = service_instances if service_instances is not None else []
        self.deployments = deployments if deployments is not None else {}

    def add_service_instance(self, instance):
        self.service_instances.append(instance)

    def add_deployment(self, deployment):
        if deployment in self.deployments:
            print(f'{self.name} already has this deployment!')
        else:
            self.deployments[deployment] = ''

    def initiate_deployment(self, deployment, person_name):
        if deployment in self.deployments:
            self.deployments[deployment] = person_name
        else:
            print(f'Sorry, we don’t have {deployment}.')

    def complete_deployment(self, deployment):
        if deployment in self.deployments:
            self.deployments[deployment] = ''
        else:
            print('Sorry, wrong registry.')

    def __str__(self):
        return self.name

def next_investment(n):
    if n == 1:
        return 2
    elif n == 2:
        return 3
    else:
        return next_investment(n - 1) * next_investment(n - 2)

def get_highest_threat_score(threat_scores):
    if len(threat_scores) == 1:
        return threat_scores[0]
    else:
        max_of_rest = get_highest_threat_score(threat_scores[1:])
        return max(threat_scores[0], max_of_rest)

def organize_students(grades):
    if len(grades) == 0:
        return []
    # passing grades
    if grades[0] >= 60:
        return [grades[0]] + organize_students(grades[1:])
    # failing grades
    else:
        return organize_students(grades[1:]) + [grades[0]]
